def solution(a, b, n):
    from math import gcd

    g = gcd(a, b)
    if n % g != 0:
        return 'No solution'
    a //= g
    b //= g
    n //= g

    def extended_gcd(a, b):
        if b == 0:
            return (a, 1, 0)
        else:
            g, x, y = extended_gcd(b, a % b)
            return (g, y, x - (a // b) * y)

    g, x, y = extended_gcd(a, b)
    x0 = x * n
    y0 = y * n

    # Find the particular solution in the range of x and y
    # We can use the formula for general solution
    # x = x0 + k * b
    # y = y0 - k * a
    # We need to find k such that x and y are integers (which they are)
    # For the purpose of this problem, we can return the first solution found

    return ('x = ', x0, ', y = ', y0)
```

