def find_ways(n):
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(pos, sum_so_far):
        if pos == n:
            return 1 if sum_so_far >= 0 else 0
        total = 0
        for i in range(1, n + 1):
            if sum_so_far + i >= 0:
                total += dp(pos + 1, sum_so_far + i)
        return total

    return dp(0, 0)
