def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    vowels = 'aeiou'
    result = []
    for char in message:
        if char.isalpha():
            # Swap case
            if char.islower():
                swapped = char.upper()
            else:
                swapped = char.lower()
            # Check if it's a vowel
            if swapped in vowels:
                # Replace with the letter 2 places ahead
                # Handle wrap-around for 'u' and 'U'
                if swapped == 'u':
                    new_char = 'w'
                elif swapped == 'U':
                    new_char = 'W'
                else:
                    new_char = chr(ord(swapped) + 2)
                result.append(new_char)
            else:
                result.append(swapped)
        else:
            result.append(char)
    return ''.join(result)
```

