def max_sub_array_sum_repeated(arr, k, n):
    def max_subarray_sum(arr):
        max_current = max_global = arr[0]
        for num in arr[1:]:
            max_current = max(num, max_current + num)
            max_global = max(max_global, max_current)
        return max_global

    if k == 1:
        return max_subarray_sum(arr)

    total_sum = sum(arr)
    max_subarray = max_subarray_sum(arr)

    if max_subarray < 0:
        return max_subarray

    max_subarray_twice = max_subarray_sum(arr + arr)
    if k == 2:
        return max_subarray_twice

    max_subarray_k_times = max_subarray_sum(arr * k)
    return max(max_subarray_k_times, max_subarray_twice + (k - 2) * total_sum)
