    @lru_cache(maxsize=None)
    def dp(pos, sum_so_far, last):
        if pos == n:
            return 1 if sum_so_far >= 0 else 0
        total = 0
        for val in [-1, 0, 1]:
            new_sum = sum_so_far + val
            if new_sum >= 0:
                total += dp(pos + 1, new_sum, val)
        return total

