def get_max_sum(n):
    memo = {}
    def max_sum(n):
        if n <= 1:
            return n
        if n in memo:
            return memo[n]
        max_val = n
        for i in [2, 3, 4, 5]:
            current = max_sum(n // i) + max_sum(n // (i + 1)) if i + 1 <= 5 else max_sum(n // i)
            max_val = max(max_val, current)
        memo[n] = max_val
        return max_val
    return max_sum(n)
```

