def extract_missing(ranges, start, end):
    ranges.sort()
    missing = []
    prev_end = start - 1
    for s, e in ranges:
        if s > prev_end + 1:
            missing.append((prev_end + 1, s - 1))
        prev_end = max(prev_end, e)
    if prev_end < end:
        missing.append((prev_end + 1, end))
    return missing
```

