def get_max_sum(n, memo={}):
    if n <= 1:
        return n
    if n in memo:
        return memo[n]
    max_sum = n
    for i in [2, 3, 4, 5]:
        max_sum = max(max_sum, get_max_sum(n // i, memo) + get_max_sum(n // (i + 1), memo))
    memo[n] = max_sum
    return max_sum
```

