def get_maxgold(grid, rows, cols):
    dp = [[0]*cols for _ in range(rows)]
    for i in range(rows):
        for j in range(cols):
            if i == 0:
                dp[i][j] = grid[i][j]
            else:
                if j == 0:
                    dp[i][j] = dp[i-1][j+1] + grid[i][j]
                elif j == cols-1:
                    dp[i][j] = dp[i-1][j-1] + grid[i][j]
                else:
                    dp[i][j] = max(dp[i-1][j-1], dp[i-1][j+1]) + grid[i][j]
    return max(max(row) for row in dp)
