def sumofFactors(n):
    sum_factors = 1
    i = 2
    while i * i <= n:
        if n % i == 0:
            if i % 2 == 0:
                sum_factors *= (i + 1)
            else:
                sum_factors *= (1 + i)
            while n % i == 0:
                n //= i
        i += 1
    if n > 1:
        if n % 2 == 0:
            sum_factors *= (n + 1)
        else:
            sum_factors *= (1 + n)
    return sum_factors
```

