    i = 2
    while i * i <= n:
        if n % i == 0:
            if i % 2 == 0:
                sum_factors *= (i * (i + 1) // 2)
            else:
                sum_factors *= (1 + i)
            while n % i == 0:
                n //= i
        i += 1
