def sumofFactors(n):
    sum_factors = 1
    i = 2
    while i * i <= n:
        if n % i == 0:
            if i % 2 == 0:
                sum_factors *= (i + 1) // 2
            else:
                sum_factors *= (i + 1)
            while n % i == 0:
                n //= i
        i += 1
    if n > 1:
        if n % 2 == 0:
            sum_factors *= (n + 1) // 2
        else:
            sum_factors *= (n + 1)
    return sum_factors
