def group_tuples(tuples):
    if not tuples:
        return []
    first_elements = [t[0] for t in tuples]
    from collections import defaultdict
    groups = defaultdict(list)
    for t in tuples:
        groups[t[0]].append(t)
    result = []
    for key in groups:
        group = groups[key]
        if len(group) > 1:
            combined = (key,)
            for t in group:
                combined += t[1:]
            result.append(combined)
        else:
            result.append(group[0])
    return result
```

